/*
 * Port of org.schabi.newpipe.database.history.model.SearchHistoryEntry
 * (Room entity `search_history`).
 */

import { relationalStore } from '@kit.ArkData';
import { colNumber, colNumberOrNull, colStringOrNull } from '../../../common/db/AppDatabase';

export class SearchHistoryEntry {
  static readonly TABLE: string = 'search_history';

  /** `id`, the autogenerated primary key. 0 until the row has been inserted. */
  id: number = 0;
  /** `creation_date`, epoch milliseconds UTC. */
  creationDate: number | null;
  /** `service_id` */
  serviceId: number;
  /** `search` — the query text, already trimmed (see MIGRATION_7_8). */
  search: string | null;

  constructor(creationDate: number | null, serviceId: number, search: string | null) {
    this.creationDate = creationDate;
    this.serviceId = serviceId;
    this.search = search;
  }

  static fromRow(rs: relationalStore.ResultSet): SearchHistoryEntry {
    const entry: SearchHistoryEntry = new SearchHistoryEntry(
      colNumberOrNull(rs, 'creation_date'),
      colNumber(rs, 'service_id'),
      colStringOrNull(rs, 'search')
    );
    entry.id = colNumber(rs, 'id');
    return entry;
  }

  toValuesBucket(): relationalStore.ValuesBucket {
    const values: relationalStore.ValuesBucket = {
      'creation_date': this.creationDate,
      'service_id': this.serviceId,
      'search': this.search
    };
    return values;
  }

  /** Port of hasEqualValues(): the id and creation date are deliberately not compared. */
  hasEqualValues(other: SearchHistoryEntry): boolean {
    return this.serviceId === other.serviceId && this.search === other.search;
  }
}
